function toOrd(int $num): string {
    $_2 = $num % 100;
    if ($_2 === 11 || $_2 === 12 || $_2 === 13) {
        return $num . 'th';
    }

    $_1 = $num % 10;
    if ($_1 === 1) {
        return $num . 'st';
    } elseif ($_1 === 2) {
        return $num . 'nd';
    } elseif ($_1 === 3) {
        return $num . 'rd';
    } else {
        return $num . 'th';
    }
}

